<?php
declare(strict_types=1);session_start();$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';if(empty($_SESSION['user'])){header('Location:index.php');exit;}$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
function te($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$perm=$_SESSION['user']['permissions']??[];$admin=($_SESSION['user']['role']??'')==='admin';if(!$admin&&empty($perm['technical_projects']['view'])&&empty($perm['technical_projects']['manage'])){http_response_code(403);exit('Sin permiso.');}$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT q.id,q.version_no,q.quote_date,p.id project_id,p.project_number,p.name project_name,p.technical_manager_user_id,c.business_name,c.city,c.province,u.name manager_name FROM quotes q JOIN projects p ON p.id=q.project_id JOIN clients c ON c.id=p.client_id LEFT JOIN users u ON u.id=p.technical_manager_user_id WHERE q.id=?');$s->execute([$id]);$q=$s->fetch();if(!$q)exit('Presupuesto inexistente.');if(!$admin&&empty($perm['technical_projects']['manage'])){$uid=(int)($_SESSION['user']['id']??0);$x=$db->prepare('SELECT 1 FROM project_technical_users WHERE project_id=? AND user_id=? UNION SELECT 1 FROM projects WHERE id=? AND technical_manager_user_id=? LIMIT 1');$x->execute([$q['project_id'],$uid,$q['project_id'],$uid]);if(!$x->fetchColumn()){http_response_code(403);exit('Proyecto no asignado.');}}$s=$db->prepare('SELECT qi.*,p.image_data,p.image_mime FROM quote_items qi LEFT JOIN products p ON p.id=qi.product_id WHERE qi.quote_id=? ORDER BY qi.block_order,qi.sort_order,qi.id');$s->execute([$id]);$items=$s->fetchAll();$labor=[];try{$s=$db->prepare('SELECT title,description,block_order FROM quote_labor_items WHERE quote_id=? ORDER BY block_order,id');$s->execute([$id]);$labor=$s->fetchAll();}catch(Throwable $e){}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ficha técnica <?=te($q['project_number'])?></title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{margin:0;background:#eee;color:#252a30;font:12px/1.45 Arial,sans-serif}.toolbar{max-width:210mm;margin:12px auto;display:flex;gap:8px}.btn{border:0;border-radius:7px;padding:10px 14px;background:#ff6702;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.sheet{width:210mm;min-height:297mm;margin:auto;background:#fff;padding:18mm;box-shadow:0 10px 30px #0002}.head{border-bottom:4px solid #ff6702;padding-bottom:8mm;margin-bottom:8mm;display:flex;justify-content:space-between}.head h1{margin:0;font-size:27px}.orange{color:#ff6702}.meta{display:grid;grid-template-columns:1fr 1fr;gap:4mm 12mm;margin-bottom:8mm}.meta div{padding:3mm;background:#f5f6f7;border-radius:6px}.section{margin-top:7mm;background:#252a30;color:#fff;padding:3mm;font-size:14px;font-weight:700}table{width:100%;border-collapse:collapse}th,td{padding:3mm;border-bottom:1px solid #ddd;text-align:left;vertical-align:middle}th{font-size:10px;text-transform:uppercase;color:#68717b}.pic{width:16mm}.pic img{max-width:12mm;max-height:12mm;object-fit:contain}.qty{width:18mm;text-align:center}.foot{margin-top:12mm;padding-top:5mm;border-top:1px solid #ddd;color:#69717a}@media print{body{background:#fff}.toolbar{display:none}.sheet{box-shadow:none;margin:0;width:auto;min-height:0;padding:0}}</style></head><body><div class="toolbar"><a class="btn" href="?a=technical_project&id=<?=$q['project_id']?>">← Proyecto técnico</a><button class="btn" onclick="window.print()">Descargar / imprimir PDF</button></div><main class="sheet"><div class="head"><div><div class="orange"><b>PUNTO DOMÓTICA</b></div><h1>Ficha técnica de proyecto</h1></div><div style="text-align:right"><b><?=te($q['project_number'])?></b><br>Presupuesto v<?=te($q['version_no'])?></div></div><div class="meta"><div><small>CLIENTE</small><br><b><?=te($q['business_name'])?></b></div><div><small>PROYECTO</small><br><b><?=te($q['project_name'])?></b></div><div><small>UBICACIÓN</small><br><?=te(trim(($q['city']??'').' '.($q['province']??'')))?></div><div><small>RESPONSABLE TÉCNICO</small><br><?=te($q['manager_name']?:'Sin asignar')?></div></div><?php $last='';foreach($items as $it):$sec=$it['section_title']?:'Materiales';if($sec!==$last):$last=$sec;?><div class="section"><?=te($sec)?></div><table><thead><tr><th class="pic">Imagen</th><th>SKU</th><th>Descripción</th><th class="qty">Cant.</th></tr></thead><tbody><?php endif;?><tr><td class="pic"><?php if(!empty($it['image_data'])&&!empty($it['image_mime'])):?><img src="data:<?=te($it['image_mime'])?>;base64,<?=base64_encode($it['image_data'])?>"><?php endif;?></td><td><b><?=te($it['sku'])?></b></td><td><?=te($it['description'])?></td><td class="qty"><?=te(rtrim(rtrim(number_format((float)$it['quantity'],2,'.',''),'0'),'.'))?></td></tr><?php $nextKey=array_search($it,$items,true);$next=$items[$nextKey+1]??null;if(!$next||($next['section_title']?:'Materiales')!==$last):?></tbody></table><?php endif;endforeach;?><?php foreach($labor as $l):?><div class="section"><?=te($l['title'])?></div><p><?=te($l['description'])?></p><?php endforeach;?><div class="foot">Documento técnico para ejecución de obra. No contiene precios, costos ni información financiera.</div></main></body></html>